    foreach(glob(loom_project_state_dir().'/*.json')?:[] as $file){$s=read_json_file($file)?:[];$before=count($s);foreach(array_keys($s) as $k){foreach($users as $uid=>$_)if(str_ends_with((string)$k,'|user|'.$uid)){unset($s[$k]);continue 2;}foreach($clients as $cid=>$_)if(str_ends_with((string)$k,'|client|'.$cid)){unset($s[$k]);continue 2;}}if(count($s)!==$before){loom_cleanup_write_json($file,$s);$counts['records']+=$before-count($s);}}
