    $n=loom_network_store();foreach(array_keys($users) as $id)unset($n['identities']['user:'.$id]);foreach(array_keys($clients) as $id)unset($n['identities']['client:'.$id]);loom_write_network_store($n);
    $c=loom_continuity_read_store();foreach(array_keys($clients) as $cid)unset($c['clients'][$cid],$c['pendingLocks'][$cid]);foreach(array_keys($guests) as $gid)unset($c['guestLocks'][$gid]);foreach(($c['clusters']??[]) as $ck=>$row){$row['guestIds']=array_values(array_filter((array)($row['guestIds']??[]),fn($x)=>!isset($guests[safe_token((string)$x)])));$row['clientIds']=array_values(array_filter((array)($row['clientIds']??[]),fn($x)=>!isset($clients[safe_token((string)$x)])));$row['profileIds']=array_values(array_filter((array)($row['profileIds']??[]),fn($x)=>!isset($profiles[safe_token((string)$x)])));$row['installationIds']=array_values(array_filter((array)($row['installationIds']??[]),fn($x)=>!isset($installs[safe_token((string)$x)])));if(loom_cleanup_matches($users,(string)($row['claimedUserId']??''))){$row['claimedUserId']=null;$row['claimedAt']=null;}if(!$row['guestIds']&&!$row['clientIds'])unset($c['clusters'][$ck]);else $c['clusters'][$ck]=$row;}foreach(['installationLocks','decisions','ambiguityEvents'] as $bucket)foreach(($c[$bucket]??[]) as $k=>$row)if(loom_cleanup_contains_ids($row,[$users,$guests,$clients,$profiles,$installs]))unset($c[$bucket][$k]);loom_cleanup_write_json(loom_continuity_file(),$c);
  }
  if($f['referrals']){$r=loom_referral_read_store();foreach(($r['shares']??[]) as $code=>$row){$a=(array)($row['referrer']??[]);if(loom_cleanup_matches($users,(string)($a['userId']??''))||loom_cleanup_matches($guests,(string)($a['guestId']??''))||loom_cleanup_matches($clients,(string)($a['clientId']??'')))unset($r['shares'][$code]);}foreach(($r['acceptances']??[]) as $k=>$row){$drop=false;foreach(['referrer','visitor'] as $side){$a=(array)($row[$side]??[]);if(loom_cleanup_matches($users,(string)($a['userId']??''))||loom_cleanup_matches($guests,(string)($a['guestId']??''))||loom_cleanup_matches($clients,(string)($a['clientId']??'')))$drop=true;}if($drop)unset($r['acceptances'][$k]);}foreach(($r['shares']??[]) as $code=>$row){$cnt=0;foreach(($r['acceptances']??[]) as $a)if(($a['shareCode']??'')===$code)$cnt++;$r['shares'][$code]['referrals']=$cnt;}loom_cleanup_write_json(loom_referral_file(),$r);}
  if($f['media']){foreach(array_keys($users) as $id)$counts['files']+=loom_cleanup_delete_media_for('user',$id);foreach(array_keys($clients) as $id)$counts['files']+=loom_cleanup_delete_media_for('client',$id);}
  if($f['activity']){foreach(glob(loom_data_dir().'/logs/*/*.jsonl')?:[] as $file)$counts['activityRows']+=loom_cleanup_filter_jsonl($file,[$users,$clients,$profiles]);foreach(glob(loom_data_dir().'/replay/*/*.jsonl')?:[] as $file)$counts['activityRows']+=loom_cleanup_filter_jsonl($file,[$users,$clients,$profiles]);foreach(glob(loom_data_dir().'/presence/*/*.json')?:[] as $file){$r=read_json_file($file);if(is_array($r)&&loom_cleanup_contains_ids($r,[$users,$clients,$profiles])){@unlink($file);$counts['files']++;}}}
  if($f['audit']){foreach(glob(loom_audit_dir().'/*.jsonl')?:[] as $file)$counts['activityRows']+=loom_cleanup_filter_jsonl($file,[$users,$guests,$clients,$profiles]);$counts['activityRows']+=loom_cleanup_filter_jsonl(loom_identity_audit_file(),[$users,$guests,$clients,$profiles]);$m=loom_moderation_store();$m['audit']=array_values(array_filter((array)($m['audit']??[]),fn($r)=>!loom_cleanup_contains_ids($r,[$users,$guests,$clients,$profiles])));loom_write_moderation_store($m);}
  // Password-reset tokens are core account data, not optional audit history.
  if(function_exists('loom_email_reset_store')){$e=loom_email_reset_store();foreach(($e['tokens']??[]) as $k=>$r)if(loom_cleanup_matches($users,(string)($r['userId']??'')))unset($e['tokens'][$k]);loom_email_write_reset_store($e);}
  if($plan['kind']==='factory-all'){@unlink(loom_admin_identity_file());@unlink(loom_access_file());$GLOBALS['loom_access_request_cache']=null;}
  return $counts;
}
function loom_cleanup_sql_in(string $column,array $ids,array &$params): string { if(!$ids)return '1=0';$params=array_merge($params,$ids);return $column.' IN ('.implode(',',array_fill(0,count($ids),'?')).')'; }
function loom_cleanup_db_exec(PDO $pdo,string $sql,array $params,array &$summary,string $label): void { try{$st=$pdo->prepare($sql);$st->execute($params);$summary['rows']+=(int)$st->rowCount();$summary['steps'][]=['label'=>$label,'rows'=>(int)$st->rowCount()];}catch(Throwable $e){$summary['skipped'][]=['label'=>$label,'reason'=>$e->getMessage()];} }
function loom_cleanup_database(array $plan): array {
  if(!loom_db_ready())throw new RuntimeException('SQL cleanup was requested, but the LOOM database is not connected.');$pdo=loom_db_pdo(true);if(!$pdo)throw new RuntimeException('Database connection unavailable.');$users=array_values($plan['userIds']);$guests=array_values($plan['guestIds']);$clients=array_values($plan['clientIds']);$profiles=array_values($plan['guestProfileIds']);$f=$plan['flags'];$s=['rows'=>0,'steps'=>[],'skipped'=>[]];
  $pdo->beginTransaction();try{
    if($plan['kind']==='factory-all')loom_cleanup_db_exec($pdo,"DELETE FROM loom_admin_state",[],$s,'system owner state');
    if($f['activity']){foreach([['loom_sessions','user_id','client_id'],['loom_events','user_id','client_id'],['loom_interaction_events','user_id','client_id']] as [$table,$uc,$cc]){$parts=[];$params=[];if($users)$parts[]=loom_cleanup_sql_in($uc,$users,$params);if($clients)$parts[]=loom_cleanup_sql_in($cc,$clients,$params);if($parts)loom_cleanup_db_exec($pdo,"DELETE FROM $table WHERE ".implode(' OR ',$parts),$params,$s,$table.' activity');}}
    if($f['audit']){$parts=[];$params=[];if($users)$parts[]=loom_cleanup_sql_in('user_id',$users,$params);if($clients)$parts[]=loom_cleanup_sql_in('client_id',$clients,$params);if($profiles)$parts[]=loom_cleanup_sql_in('guest_profile_id',$profiles,$params);if($parts)loom_cleanup_db_exec($pdo,"DELETE FROM loom_audit_events WHERE ".implode(' OR ',$parts),$params,$s,'audit events');$parts=[];$params=[];if($users){$parts[]=loom_cleanup_sql_in('admin_user_id',$users,$params);$parts[]=loom_cleanup_sql_in('target_id',$users,$params);}if($clients)$parts[]=loom_cleanup_sql_in('admin_client_id',$clients,$params);if($parts)loom_cleanup_db_exec($pdo,"DELETE FROM loom_admin_audit WHERE ".implode(' OR ',$parts),$params,$s,'admin audit');}
    $modParts=[];$modParams=[];if($users){$modParams[]='user';$modParams=array_merge($modParams,$users);$modParts[]='(subject_type=? AND subject_id IN ('.implode(',',array_fill(0,count($users),'?')).'))';}if($guests){$modParams[]='guest';$modParams=array_merge($modParams,$guests);$modParts[]='(subject_type=? AND subject_id IN ('.implode(',',array_fill(0,count($guests),'?')).'))';}if($modParts)loom_cleanup_db_exec($pdo,"DELETE FROM loom_identity_moderation WHERE ".implode(' OR ',$modParts),$modParams,$s,'canonical moderation');
    if($f['projectData']){foreach([['loom_project_module_state','owner_type','owner_id'],['loom_project_identities','owner_type','owner_id'],['loom_project_user_state','subject_type','subject_id']] as [$table,$tc,$ic]){$parts=[];$params=[];if($users){$params[]='user';$params=array_merge($params,$users);$parts[]="($tc=? AND $ic IN (".implode(',',array_fill(0,count($users),'?'))."))";}if($clients){$params[]='client';$params=array_merge($params,$clients);$parts[]="($tc=? AND $ic IN (".implode(',',array_fill(0,count($clients),'?'))."))";}if($parts)loom_cleanup_db_exec($pdo,"DELETE FROM $table WHERE ".implode(' OR ',$parts),$params,$s,$table);}}
    if($f['continuity']){foreach([['user',$users],['client',$clients]] as [$type,$ids])if($ids){$params=[$type];$cond=loom_cleanup_sql_in('owner_id',$ids,$params);loom_cleanup_db_exec($pdo,"DELETE FROM loom_identity_ips WHERE owner_type=? AND $cond",$params,$s,'network identity history');}}
    if($profiles){$params=[];$cond=loom_cleanup_sql_in('guest_profile_id',$profiles,$params);loom_cleanup_db_exec($pdo,"DELETE FROM loom_guest_profile_installations WHERE $cond",$params,$s,'guest profile installations');loom_cleanup_db_exec($pdo,"DELETE FROM loom_guest_profile_generations WHERE $cond",$params,$s,'guest profile generations');loom_cleanup_db_exec($pdo,"DELETE FROM loom_guest_profiles WHERE $cond",$params,$s,'guest profiles');}
    elseif($users){$params=[];$cond=loom_cleanup_sql_in('user_id',$users,$params);loom_cleanup_db_exec($pdo,"UPDATE loom_guest_profile_generations SET user_id=NULL,status=IF(status='claimed','active',status),claimed_at=NULL WHERE $cond",$params,$s,'detach guest generations');$params=[];$cond=loom_cleanup_sql_in('last_claimed_user_id',$users,$params);loom_cleanup_db_exec($pdo,"UPDATE loom_guest_profiles SET last_claimed_user_id=NULL WHERE $cond",$params,$s,'detach guest profiles');}
    if($guests){$params=[];$cond=loom_cleanup_sql_in('guest_id',$guests,$params);foreach(['loom_guest_recovery','loom_identity_attachments','loom_identity_merge_conflicts','loom_guest_clients','loom_guest_identities'] as $table)loom_cleanup_db_exec($pdo,"DELETE FROM $table WHERE $cond",$params,$s,$table);}
    elseif($users){$params=[];$cond=loom_cleanup_sql_in('user_id',$users,$params);loom_cleanup_db_exec($pdo,"DELETE FROM loom_identity_attachments WHERE $cond",$params,$s,'identity attachments');loom_cleanup_db_exec($pdo,"DELETE FROM loom_identity_merge_conflicts WHERE $cond",$params,$s,'identity merge conflicts');$params=[];$cond=loom_cleanup_sql_in('attached_user_id',$users,$params);loom_cleanup_db_exec($pdo,"UPDATE loom_guest_identities SET attached_user_id=NULL,attached_at=NULL,status=IF(status='attached','unattached',status) WHERE $cond",$params,$s,'detach surviving guests');}
    foreach([['user',$users],['client',$clients]] as [$type,$ids])if($ids){$params=[$type];$cond=loom_cleanup_sql_in('owner_id',$ids,$params);loom_cleanup_db_exec($pdo,"DELETE FROM loom_global_profiles WHERE owner_type=? AND $cond",$params,$s,'global profiles');loom_cleanup_db_exec($pdo,"DELETE FROM loom_username_registry WHERE owner_type=? AND $cond",$params,$s,'username registry');}
    if($users){$params=[];$cond=loom_cleanup_sql_in('user_id',$users,$params);loom_cleanup_db_exec($pdo,"DELETE FROM loom_auth_sessions WHERE $cond",$params,$s,'auth sessions');loom_cleanup_db_exec($pdo,"DELETE FROM loom_user_avatar_profiles WHERE $cond",$params,$s,'avatar metadata');loom_cleanup_db_exec($pdo,"DELETE FROM loom_user_clients WHERE $cond",$params,$s,'user/client links');loom_cleanup_db_exec($pdo,"UPDATE loom_clients SET user_id=NULL WHERE $cond",$params,$s,'client account links');loom_cleanup_db_exec($pdo,"DELETE FROM loom_users WHERE $cond",$params,$s,'permanent accounts');}
    if($clients){$params=[];$cond=loom_cleanup_sql_in('c.client_id',$clients,$params);loom_cleanup_db_exec($pdo,"DELETE c FROM loom_client_profiles c LEFT JOIN loom_user_clients u ON u.client_id=c.client_id LEFT JOIN loom_clients lc ON lc.client_id=c.client_id WHERE $cond AND u.client_id IS NULL AND (lc.user_id IS NULL OR lc.user_id='')",$params,$s,'orphan guest client profiles');$params=[];$cond=loom_cleanup_sql_in('c.client_id',$clients,$params);loom_cleanup_db_exec($pdo,"DELETE c FROM loom_clients c LEFT JOIN loom_user_clients u ON u.client_id=c.client_id WHERE $cond AND u.client_id IS NULL AND (c.user_id IS NULL OR c.user_id='')",$params,$s,'orphan guest clients');}
    $pdo->commit();return $s;
  }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function loom_identity_cleanup_preview(string $kind,string $subjectId,array $options=[]): array { $p=loom_cleanup_plan($kind,$subjectId,$options);return ['ok'=>true,'plan'=>$p,'databaseReady'=>loom_db_ready(),'message'=>'Preview only. Nothing has been deleted.']; }
function loom_identity_cleanup_execute(string $kind,string $subjectId,array $options,string $confirmPhrase): array {
  $p=loom_cleanup_plan($kind,$subjectId,$options);if($kind==='factory-all'&&loom_db_ready()&&$p['scope']!=='both')throw new RuntimeException('Factory identity wipe requires Durable local + SQL together while a database is connected.');if(!hash_equals((string)$p['confirmPhrase'],trim($confirmPhrase)))throw new RuntimeException('Confirmation phrase did not match. Preview again and type the exact phrase shown.');if(in_array($p['scope'],['database','both'],true)&&!loom_db_ready())throw new RuntimeException('SQL cleanup was selected, but the database is not connected. Nothing was deleted.');
  $result=['local'=>null,'database'=>null];if(in_array($p['scope'],['local','both'],true))$result['local']=loom_cleanup_local($p);if(in_array($p['scope'],['database','both'],true))$result['database']=loom_cleanup_database($p);
  if($kind!=='factory-all')loom_admin_audit('identity.permanent-delete','identity',$subjectId,'',['kind'=>$kind,'scope'=>$p['scope'],'counts'=>$p['counts'],'flags'=>$p['flags']]);
  return ['ok'=>true,'deleted'=>true,'plan'=>$p,'result'=>$result,'ownerReset'=>$kind==='factory-all','message'=>$kind==='factory-all'?'Identity factory wipe complete. LOOM has returned to first-run Admin ownership state.':'Permanent identity deletion completed.'];
}
